//! The document types generated from the official schemas in `spec/` by the `codegen` crate.

/// Generated by `cargo run -p codegen` from `spec/Schema_VFPR12_v1.2.3.xsd`, version 1.2.3. Do not edit by hand.
#[expect(
    clippy::default_trait_access,
    clippy::ignored_unit_patterns,
    clippy::large_enum_variant,
    clippy::len_zero,
    clippy::match_same_arms,
    clippy::match_wildcard_for_single_variants,
    clippy::no_effect_underscore_binding,
    clippy::redundant_else,
    clippy::redundant_field_names,
    clippy::semicolon_if_nothing_returned,
    clippy::single_match,
    clippy::too_many_lines,
    clippy::unnecessary_wraps,
    missing_docs,
    unused_variables,
    dead_code,
    reason = "generated by xsd-parser; the lints are generator noise, not crate policy"
)]
#[cfg_attr(
    not(test),
    expect(
        clippy::missing_docs_in_private_items,
        reason = "clippy skips this lint in test builds"
    )
)]
#[rustfmt::skip]
pub mod fpr12;

